LogicDefinition.ScriptText:
#load "reference"

//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//                                                                                                          //
//    Logik:           Grob_AxisSiemens                                                                     //
//                                                                                                          //
//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//
//    Datum            Version        Autor            Beschreibung
//
//    04.06.2025       1.10.0         Greif            Header integriert
//    14.10.2025       1.10.1         Egg              Name geändert
//
//============================================================================================================
//
//    SW-Standard      Geprüft        Prüfer           Allgemeine Informationen
//                     
//    FEE-Siemens      x              Greif            Konvertiert die Achsposition 
/*
//============================================================================================================
//
//    Beschreibung:
//
//    Die Logik konvertiert die Achsposition am Eingang (PLC_OUT_AxisValue) von der Einheit Millimeter in Meter,
//    wenn das Bit (PAR_AxisIsRotary=0) ist und gibt dies an (SIM_InValue_Joint) aus.
//    Andernfalls wird am Ausgang die Position als Millimeter ausgegeben.
//    Die Steuersignale (PLC_OUT_ALM_ControlWord und PLC_OUT_Axis_ControlWord) werden erfasst, beschrieben und 
//    als Status (PLC_IN_ALM_StatusWord und PLC_IN_Axis_StatusWord) ausgegeben.
//
//============================================================================================================
//
//    Input Slot Values
//    PLC_OUT_ALM_ControlWord       =   Word, Alm Steuerungssignale erhalten
//    PLC_OUT_Axis_ControlWord      =   DWord, Achse Steuerungssignale erhalten
//    PLC_OUT_AxisValue             =   Real, Achsposition [mm]
//    PAR_AxisIsRotary              =   Bool, Achse ist rotatorisch
//
//    Output Slot Values
//    PLC_IN_ALM_StatusWord         =   Word, Alm Status ausgeben
//    PLC_IN_Axis_StatusWord        =   DWord, Achse Status ausgeben
//    PLC_IN_Axis_SafePosition      =   Dint, Achsposition [mm]
//    SIM_InValue_Joint             =   Real, Achsposition [mm] oder [m]
//    
//============================================================================================================
*/
//////////////////////////////////////////////////////////////////////////////////////////////////////////////

#region Achsposition konvertieren
//============================================================================================================
// A C H S P O S I T I O N    K O N V E R T I E R E N
//============================================================================================================

if(PLC_OUT_AxisValue != _lastAxisValue)
{
    // Axis Conversion mm -> m on linear axes
    if(!PAR_AxisIsRotary)
    {
        SIM_InValue_Joint = PLC_OUT_AxisValue * 0.001f;
    }
    else
    {
        SIM_InValue_Joint = PLC_OUT_AxisValue;
    }

    // Set Safe Position
    PLC_IN_Axis_SafePosition = Convert.ToInt32(PLC_OUT_AxisValue);
}
_lastAxisValue = PLC_OUT_AxisValue;




#endregion



#region ALM-Telegram 370
//============================================================================================================
// A L M - T E L E G R A M    3 7 0
//============================================================================================================

// Split ALM Word
ConvertFunctions.UShortToBool(PLC_OUT_ALM_ControlWord,
// Byte 1
    x00: out alm_Q1_0,
    x01: out alm_Q1_1,
    x02: out alm_Q1_2,
    x03: out alm_Q1_3__EnableOperation,
    x04: out alm_Q1_4,
    x05: out alm_Q1_5,
    x06: out alm_Q1_6,
    x07: out alm_Q1_7,
// Byte 0    
    x08: out alm_Q0_0,
    x09: out alm_Q0_1,
    x10: out alm_Q0_2,
    x11: out alm_Q0_3,
    x12: out alm_Q0_4,
    x13: out alm_Q0_5,
    x14: out alm_Q0_6,
    x15: out alm_Q0_7);

// Signals ALM
alm_I1_2__OperationEnabled = alm_Q1_3__EnableOperation;

// Write ALM Word
PLC_IN_ALM_StatusWord = ConvertFunctions.BoolToUShort(
                    // Byte 1
                        x00: alm_I1_0,
                        x01: alm_I1_1,
                        x02: alm_I1_2__OperationEnabled,
                        x03: alm_I1_3,
                        x04: alm_I1_4,
                        x05: alm_I1_5,
                        x06: alm_I1_6,
                        x07: alm_I1_7,
                    // Byte 0
                        x08: alm_I0_0,
                        x09: alm_I0_1,
                        x10: alm_I0_2,
                        x11: alm_I0_3,
                        x12: alm_I0_4,
                        x13: alm_I0_5,
                        x14: alm_I0_6,
                        x15: alm_I0_7);

# endregion   


#region Axis Telegram 902
//============================================================================================================
// A C H S    T E L E G R A M    9 0 2
//============================================================================================================    

// Split Axis DWord
ConvertFunctions.UIntToBool(PLC_OUT_Axis_ControlWord,
// Byte 3
    x00: out axis_Q3_0,
    x01: out axis_Q3_1,
    x02: out axis_Q3_2,
    x03: out axis_Q3_3,
    x04: out axis_Q3_4,
    x05: out axis_Q3_5,
    x06: out axis_Q3_6,
    x07: out axis_Q3_7,
// Byte 2 
    x08: out axis_Q2_0,
    x09: out axis_Q2_2,
    x10: out axis_Q2_2,
    x11: out axis_Q2_3,
    x12: out axis_Q2_4,
    x13: out axis_Q2_5,
    x14: out axis_Q2_6,
    x15: out axis_Q2_7,
// Byte 1
    x16: out axis_Q1_0__SLA,
    x17: out axis_Q1_1__SelectSLSbit0,
    x18: out axis_Q1_2__SelectSLSbit1,
    x19: out axis_Q1_3,
    x20: out axis_Q1_4,
    x21: out axis_Q1_5,
    x22: out axis_Q1_6,
    x23: out axis_Q1_7,
// Byte 0
    x24: out axis_Q0_0__STO,
    x25: out axis_Q0_1__SS1,
    x26: out axis_Q0_2__SS2,
    x27: out axis_Q0_3__SOS,
    x28: out axis_Q0_4__SLS,
    x29: out axis_Q0_5,
    x30: out axis_Q0_6__SLP,
    x31: out axis_Q0_7__internalEventAckn);


// Signales Axis
// Byte 0
axis_I0_0__STOactive = axis_Q0_0__STO && !axis_Q0_1__SS1;
axis_I0_1__SS1active = !axis_Q0_1__SS1;
axis_I0_2__SS2active = axis_Q0_2__SS2;
axis_I0_3__SOSactive = axis_Q0_3__SOS;

axis_I0_6__SPLactive = axis_Q0_6__SLP;

// Byte 1
axis_I1_0__SLAactive = axis_Q1_0__SLA;
axis_I1_1__SLSbit0active = axis_Q1_1__SelectSLSbit0;
axis_I1_2__SLSbit1active = axis_Q1_2__SelectSLSbit1;

axis_I1_7__SSMactive = true;

// Byte 2
axis_I2_6__safePositionValid = true;
axis_I2_7__safelyReferenced = true;

// Write Axis DWord
PLC_IN_Axis_StatusWord = ConvertFunctions.BoolToUint(
// Byte 3
    x00: axis_I3_0,
    x01: axis_I3_1,
    x02: axis_I3_2,
    x03: axis_I3_3,
    x04: axis_I3_4,
    x05: axis_I3_5,
    x06: axis_I3_6,
    x07: axis_I3_7,
// Byte 2
    x08: axis_I2_0,
    x09: axis_I2_1,
    x10: axis_I2_2,
    x11: axis_I2_3,
    x12: axis_I2_4,
    x13: axis_I2_5,
    x14: axis_I2_6__safePositionValid,
    x15: axis_I2_7__safelyReferenced,
// Byte 1  
    x16: axis_I1_0__SLAactive,
    x17: axis_I1_1__SLSbit0active,
    x18: axis_I1_2__SLSbit1active,
    x19: axis_I1_3,
    x20: axis_I1_4,
    x21: axis_I1_5,
    x22: axis_I1_6,
    x23: axis_I1_7__SSMactive,
// Byte 0    
    x24: axis_I0_0__STOactive,
    x25: axis_I0_1__SS1active,
    x26: axis_I0_2__SS2active,
    x27: axis_I0_3__SOSactive,
    x28: axis_I0_4__SLSactive,
    x29: axis_I0_5,
    x30: axis_I0_6__SPLactive,
    x31: axis_I0_7__internalEvent);

#endregion
